from lib import *
L = lambda *a, **k: lesson(43, "A1", *a, **k)
V = "verb"
N = "noun"
A = "adjective"
L(1, "Який він на вигляд?", "Спитати про зовнішність і відповісти загалом.",
 "What does he look like? — «Який він на вигляд?» Відповідь: He is tall and slim. Is + прикметник (tall, slim) і has + частина тіла (He has dark hair). Describe — описувати, appearance — зовнішність.",
 [W("look like", "/ˈlʊk laɪk/", "phrase", "виглядати як", "What does she look like?", "Як вона виглядає?"),
  W("describe", "/dɪˈskraɪb/", V, "описувати", "Can you describe him?", "Ви можете його описати?"),
  W("appearance", "/əˈpɪərəns/", N, "зовнішність", "His appearance is neat.", "Його зовнішність охайна."),
  W("slim", "/slɪm/", A, "стрункий", "She is tall and slim.", "Вона висока й струнка."),
  W("medium height", "/ˌmiːdiəm ˈhaɪt/", "phrase", "середнього зросту", "He is of medium height.", "Він середнього зросту.")],
 [li("Have you got a brother?", "Повторимо. Ні. Що відповісти?", ["No, I haven't.", "No, I don't have.", "No, I'm not."], "No, I haven't."),
  mt([("look like", "виглядати як"), ("describe", "описувати"), ("appearance", "зовнішність"), ("slim", "стрункий"), ("medium height", "середнього зросту")], "Слова для опису зовнішності."),
  liu("What does she look like?", "Прослухайте. Про що питають?", ["Як вона виглядає", "Де вона живе", "Ким вона працює"], "Look like."),
  liu("She is tall and slim.", "Прослухайте. Яка жінка?", ["Висока й струнка", "Низька й струнка", "Висока й повна"], "Tall and slim."),
  liu("He is of medium height.", "Прослухайте. Який він на зріст?", ["Середній", "Високий", "Низький"], "Medium height."),
  fb("What does he ___ like?", ["look", "looks", "looking"], "What does he look like?"),
  fb("She is tall and ___.", ["slim", "slims", "slimming"], "Slim."),
  fb("Can you ___ him?", ["describe", "appearance", "slim"], "Describe."),
  mc("Як спитати про зовнішність?", ["What does he look like?", "How does he look like?", "What he looks like?"], "What does he look like?"),
  bs("Вона висока й струнка.", ["She", "is", "tall", "and", "slim"], ["has", "are"], "She is tall and slim."),
  tr("Як вона виглядає?", ["What does she look like"], "What does she look like?"),
  li("What does your brother look like?", "Він високий. Що відповісти?", ["He is tall.", "He has tall.", "He looks like tall."], "He is tall.")])
