  liu("He has curly hair.", "Прослухайте. Яке в нього волосся?", ["Кучеряве", "Пряме", "Лисий"], "Curly."),
  liu("My uncle is bald and he has a moustache.", "Прослухайте. Що є в дядька?", ["Вуса", "Борода", "Окуляри"], "A moustache."),
  fb("She has ___ hair.", ["blonde", "bald", "moustache"], "Blonde hair."),
  fb("My uncle ___ bald.", ["is", "has", "have"], "Is bald."),
  fb("He ___ a moustache.", ["has", "is", "have"], "Has a moustache."),
  mc("Як сказати «У неї пряме волосся»?", ["She has straight hair.", "She is straight hair.", "She have straight hair."], "Has straight hair."),
  bs("У нього кучеряве волосся.", ["He", "has", "curly", "hair"], ["is", "have"], "He has curly hair."),
  tr("Мій дядько лисий.", ["My uncle is bald"], "My uncle is bald."),
