  mt([("handsome", "гарний (чол.)"), ("pretty", "гарненька"), ("good-looking", "привабливий"), ("stylish", "стильний"), ("elegant", "елегантний")], "Слова-компліменти."),
  liu("He is very handsome.", "Прослухайте. Що кажуть про чоловіка?", ["Що він гарний", "Що він високий", "Що він лисий"], "Handsome."),
  liu("Your jacket is stylish.", "Прослухайте. Що стильне?", ["Куртка", "Капелюх", "Сумка"], "The jacket."),
  liu("She looks elegant in that dress.", "Прослухайте. У чому вона елегантна?", ["У сукні", "У куртці", "У костюмі"], "Dress."),
  fb("She is ___. (гарненька)", ["pretty", "handsome", "bald"], "Pretty — про жінку."),
  fb("He is very ___. (гарний)", ["handsome", "pretty", "curly"], "Handsome — про чоловіка."),
  fb("Your jacket is ___.", ["stylish", "pale", "scar"], "Stylish."),
  mc("Яке слово підійде і для чоловіка, і для жінки?", ["good-looking", "handsome", "pretty"], "Good-looking — універсальне."),
  bs("Вона виглядає елегантно.", ["She", "looks", "elegant"], ["is", "look"], "She looks elegant."),
